// Everyday language and progressive disclosure; existing workflows remain available.
function simpleNext(p){const busy=(opsData?.orders||[]).some(o=>o.plot_id===p.id&&!['done','cancelled'].includes(o.status));if(busy)return 'Садовник получил вашу заявку. Следите за ходом работ.';return ({unchecked:'Начните с осмотра: садовник проверит, готова ли грядка к посадке.',empty:'Следующий шаг — подготовить почву.',ready:'Выберите, что хотите вырастить. Садовник поможет с посадкой.',planted:'Посадки на месте. Уход выполняется по согласованному плану.',growing:'Ваши овощи растут. Можно посмотреть камеру или заказать уход.',harvest_ready:'Урожай созрел! Пора заказать сбор.',finished:'Сезон завершён. Можно подготовить грядку к новой посадке.'})[p.growing_state]||'Садовник поможет выбрать следующий шаг.'}
cloudHome=function(){if(!myPlots().length)return emptyFarm();return heading('Моё хозяйство','Вы выбираете овощи — садовник заботится о грядках.','<a class="btn" href="#choose-bed">＋ Арендовать грядку</a>')+`<div class="grid">${myPlots().map(p=>`<article class="card"><a class="room-card-link" href="#bed-${p.id}" aria-label="Открыть грядку №${p.id}"><div class="plot-art"><span>🌱</span><b>№${p.id}</b><div class="tag">${esc(p.sign||'Моя грядка')}</div></div></a><div class="cardbody"><h3><a href="#bed-${p.id}">${esc(p.name)}</a></h3><p>${esc(p.crop||'Пока ничего не посажено')} · ${p.size} м²</p><p>${simpleNext(p)}</p><a class="btn" href="#bed-${p.id}">Открыть грядку →</a></div></article>`).join('')}</div><div class="quick-actions"><a href="#lifecycle">🧺 Урожай и доставка</a><a href="#orders">🌿 Мои заявки</a><a href="#notifications">🔔 Что нового</a></div><details class="panel"><summary>Ещё возможности хозяйства</summary><div class="quick-actions"><a href="#warehouse">Мои запасы</a><a href="#season">Календарь и итоги</a><a href="#planner">План посадок</a><a href="#journal">Дневник</a><a href="#guide">Помощь</a></div></details>`};
plotRoomTabs.grow='🌱 Уход';plotRoomTabs.build='🪵 Улучшения';plotRoomTabs.camera='📹 Посмотреть';
const detailedPlotRoom=plotRoom;
plotRoom=function(){let html=detailedPlotRoom();const p=currentRoomPlot();if(!p||plotRoomTab!=='grow')return html;const intro=`<section class="panel"><h2>Что делать дальше</h2><p>${simpleNext(p)}</p><button class="btn light" onclick="lifeRequest('kit',${p.id})">Помогите выбрать овощи</button> <button class="btn light" onclick="lifeRequest('autocare',${p.id})">Хочу поручить уход садовнику</button><p class="note">Сначала обсудим состав работ, цену и сроки. Заявка ничего не списывает.</p></section>`;return html.replace('<div class="room-actions">',intro+'<div class="room-actions">')};
const beforeSimpleRender=render;
render=function(){beforeSimpleRender();const r=location.hash.slice(1)||'home';statusBanner.textContent='Тестовый режим · оплата с демобаланса, реальные деньги не списываются';document.querySelector('header>span:nth-child(2)').textContent='Белореченск';if(r==='home'||r.startsWith('bed-'))document.querySelectorAll('#app > .context-tabs').forEach(el=>el.remove());if(r==='home'&&!myPlots().length){const button=document.querySelector('.empty-farm .btn');if(button)button.textContent='Выбрать грядку'}document.querySelectorAll('nav a').forEach(a=>{if(a.hash==='#orders')a.textContent='☷ Мои заявки';if(a.hash==='#notifications')a.textContent='◉ Уведомления'});};render();
